@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container py-4">
    <h2>🔍 Track Your Shipment</h2>
    <p class="text-muted">Enter your tracking number below to see the current status and estimated delivery.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. TRK-100001"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search" disabled="@isLoading">
                    @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Search
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null && !isLoading)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>". Please check and try again.
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>@shipment.TrackingNumber</strong>
                <span class="badge @StatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Recipient</dt>
                            <dd>@(shipment.RecipientName ?? "—")</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped On</dt>
                            <dd>@shipment.CreatedAt.ToString("MMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    <span class="fw-bold">@shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</span>
                                }
                                else
                                {
                                    <span>—</span>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>
                @if (!string.IsNullOrWhiteSpace(shipment.Notes))
                {
                    <div class="alert alert-info mt-2 mb-0">
                        <strong>Notes:</strong> @shipment.Notes
                    </div>
                }

                <!-- Progress tracker -->
                <div class="mt-4">
                    <h6>Shipment Progress</h6>
                    <div class="progress" style="height: 24px;">
                        <div class="progress-bar @ProgressBarClass(shipment.Status)"
                             role="progressbar"
                             style="width: @ProgressPercent(shipment.Status)%">
                            @FormatStatus(shipment.Status)
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool isLoading;
    private bool searched;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        searched = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        isLoading = false;
    }

    private static string FormatStatus(ShipmentStatus s) => s switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Cancelled => "Cancelled",
        _ => s.ToString()
    };

    private static string StatusBadgeClass(ShipmentStatus s) => s switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };

    private static string ProgressBarClass(ShipmentStatus s) => s switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary"
    };

    private static int ProgressPercent(ShipmentStatus s) => s switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

