+                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                                    {
+                                        <option value="@((int)status)">@FormatStatus(status)</option>
+                                    }
+                                </select>
+                            </td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        </div>
+    }
+</div>
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string searchTerm = string.Empty;
+    private string statusFilter = string.Empty;
+    private bool isLoading;
+    private int? updatingId;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task HandleSearchKey(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter") await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        isLoading = true;
+        errorMessage = null;
+        try
+        {
+            shipments = await ShipmentService.GetShipmentsAsync(
+                string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
+                string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load shipments: {ex.Message}";
+        }
+        isLoading = false;
+    }
+
+    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
+    {
+        if (e.Value is null) return;
+        var newStatus = (ShipmentStatus)int.Parse(e.Value.ToString()!);
+        if (newStatus == shipment.Status) return;
+
+        updatingId = shipment.Id;
+        errorMessage = null;
+        try
+        {
+            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
+            if (updated is not null)
+            {
+                shipment.Status = updated.Status;
+            }
+            else
+            {
+                errorMessage = $"Failed to update shipment {shipment.TrackingNumber}.";
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Error updating status: {ex.Message}";
+        }
+        updatingId = null;
+    }
+
+    private static string FormatStatus(ShipmentStatus s) => s switch
+    {
+        ShipmentStatus.Pending => "Pending",
+        ShipmentStatus.PickedUp => "Picked Up",
+        ShipmentStatus.InTransit => "In Transit",
+        ShipmentStatus.OutForDelivery => "Out for Delivery",
+        ShipmentStatus.Delivered => "Delivered",
+        ShipmentStatus.Cancelled => "Cancelled",
+        _ => s.ToString()
+    };
+
+    private static string StatusBadgeClass(ShipmentStatus s) => s switch
+    {
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        ShipmentStatus.OutForDelivery => "bg-info text-dark",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.PickedUp => "bg-warning text-dark",
+        _ => "bg-secondary"
+    };
+}
